+function Read-ConfigStore {
+    param([Parameter(Mandatory)][string]$Path)
+
+    $config = [ordered]@{}
+    if (-not (Test-Path -LiteralPath $Path)) {
+        return $config
+    }
+
+    $content = Get-Content -LiteralPath $Path -Raw
+    if ([string]::IsNullOrWhiteSpace($content)) {
+        return $config
+    }
+
+    $parsed = ConvertFrom-Json -InputObject $content
+    foreach ($name in @('dataFile', 'defaultJson')) {
+        if ($parsed.PSObject.Properties.Name -contains $name) {
+            $config[$name] = $parsed.$name
+        }
+    }
+    return $config
+}
+
+function Write-ConfigStore {
+    param(
+        [Parameter(Mandatory)][string]$Path,
+        [Parameter(Mandatory)][System.Collections.IDictionary]$Config
+    )
+
+    $parent = Split-Path -Parent $Path
+    if ($parent -and -not (Test-Path -LiteralPath $parent)) {
+        New-Item -ItemType Directory -Path $parent -Force | Out-Null
+    }
+
+    $temporary = "$Path.$PID.tmp"
+    $json = ConvertTo-Json -InputObject ([pscustomobject]$Config) -Depth 5
+    [System.IO.File]::WriteAllText($temporary, "$json`n", [System.Text.UTF8Encoding]::new($false))
+    Move-Item -LiteralPath $temporary -Destination $Path -Force
+}
+
+function Resolve-ConfigPath {
+    param(
+        [Parameter(Mandatory)][string]$ConfigFile,
+        [Parameter(Mandatory)][string]$RelativePath
+    )
+
+    if ([System.IO.Path]::IsPathRooted($RelativePath)) {
+        return [System.IO.Path]::GetFullPath($RelativePath)
+    }
+    $configDir = Split-Path -Parent ([System.IO.Path]::GetFullPath($ConfigFile))
+    return [System.IO.Path]::GetFullPath((Join-Path $configDir $RelativePath))
+}
+
+function ConvertTo-ConfigBoolean {
+    param([Parameter(Mandatory)][AllowEmptyString()][string]$Value)
+
+    switch (([string]$Value).Trim().ToLowerInvariant()) {
+        'true' { return $true }
+        'false' { return $false }
+        default { throw "Invalid boolean value: '$Value'. Use 'true' or 'false'." }
+    }
+}
+
+function Format-ConfigValue {
+    param([AllowNull()]$Value)
+
+    if ($Value -is [bool]) {
+        return ($(if ($Value) { 'true' } else { 'false' }))
+    }
+    return [string]$Value
+}
+
+function Get-ConfigBanner {
+    param([Parameter(Mandatory)][string]$AssetPath)
+
+    if (-not (Test-Path -LiteralPath $AssetPath)) {
+        return $null
+    }
+    return (Get-Content -LiteralPath $AssetPath -Raw).TrimEnd("`r", "`n")
+}
